const resp = $input.first().json;
if (resp && resp.status === 'SUCCESS' && Array.isArray(resp.people) && resp.people.length > 0) {
  return resp.people.map((p) => ({ json: { ...p, source: resp.provider } }));
}

// Local safety-net only -- fires if the app endpoint itself was
// unreachable (the app's own provider chain already falls back to mock
// internally, so this path is rare). Matches lib/providers/lead/mock.ts.
console.log('APP_LEAD_PROVIDER_UNREACHABLE_OR_EMPTY');
const company = $('Start (called by WF_01)').first().json;
const seed = company.name.length;
const titles = [{t:'Founder & CEO',r:'FOUNDER'},{t:'Co-Founder',r:'FOUNDER'},{t:'Head of E-commerce',r:'ECOMMERCE'},{t:'Marketing Director',r:'MARKETING'},{t:'Brand Manager',r:'MARKETING'}];
const firsts=['Jordan','Taylor','Morgan','Casey','Riley','Avery']; const lasts=['Bennett','Clarke','Douglas','Reyes','Kim','Patel'];
const count = 1 + (seed % 3); const out=[];
for (let i=0;i<count;i++) {
  const pick = titles[(seed+i)%titles.length];
  const found = (seed+i) % 3 !== 0;
  const first = firsts[(seed+i)%6], last = lasts[(seed+i*3)%6];
  out.push({ json: { name: `${first} ${last}`, jobTitle: pick.t, roleCategory: pick.r,
    linkedinUrl: found ? `https://www.linkedin.com/in/${first.toLowerCase()}-${last.toLowerCase()}` : null,
    linkedinStatus: found ? 'FOUND' : 'NOT_FOUND', location: company.location, confidence: found?0.8:0.55, source: 'mock-lead' } });
}
return out;
